import { useCallback, useLayoutEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [view, setView] = useState({ results: [], phase: "idle" });

  const valueRef = useRef("");
  const searchRef = useRef(search);
  const timerRef = useRef(null);
  const latestRequestRef = useRef(null);

  useLayoutEffect(() => {
    searchRef.current = search;
  }, [search]);

  const clearTimer = useCallback(() => {
    const timer = timerRef.current;
    timerRef.current = null;
    if (timer !== null) clearTimeout(timer);
  }, []);

  const abortLatest = useCallback(() => {
    const request = latestRequestRef.current;
    latestRequestRef.current = null;
    if (request) request.controller.abort();
  }, []);

  const reset = useCallback(() => {
    clearTimer();
    abortLatest();
    setView((current) =>
      current.phase === "idle" && current.results.length === 0
        ? current
        : { results: [], phase: "idle" }
    );
  }, [clearTimer, abortLatest]);

  const startRequest = useCallback(
    (query, force = false) => {
      clearTimer();

      if (query.length < minChars) {
        reset();
        return;
      }

      const previous = latestRequestRef.current;

      if (
        !force &&
        previous &&
        previous.query === query &&
        !previous.controller.signal.aborted &&
        (previous.phase === "loading" || previous.phase === "success")
      ) {
        return;
      }

      const controller = new AbortController();
      const request = { query, controller, phase: "loading" };

      // Supersede the old request before aborting it.
      latestRequestRef.current = request;

      const isCurrent = () =>
        latestRequestRef.current === request && !controller.signal.aborted;

      if (previous) previous.controller.abort();
      if (!isCurrent()) return;

      setView((current) => ({
        results: current.results,
        phase: "loading",
      }));

      const handleFailure = (error) => {
        if (!isCurrent()) return;

        if (error?.name === "AbortError") {
          request.phase = "aborted";
          setView((current) => ({
            results: current.results,
            phase: "idle",
          }));
          return;
        }

        request.phase = "error";
        setView({ results: [], phase: "error" });
      };

      try {
        const searchFunction = searchRef.current;
        Promise.resolve(
          searchFunction(query, { signal: controller.signal })
        ).then((results) => {
          if (!isCurrent()) return;

          request.phase = "success";
          setView({ results, phase: "success" });
        }, handleFailure);
      } catch (error) {
        handleFailure(error);
      }
    },
    [clearTimer, minChars, reset]
  );

  const schedule = useCallback(
    (rawValue) => {
      clearTimer();
      const query = rawValue.trim();

      if (query.length < minChars) {
        reset();
        return;
      }

      const timer = setTimeout(() => {
        if (timerRef.current !== timer) return;
        timerRef.current = null;
        startRequest(query);
      }, debounceMs);

      timerRef.current = timer;
    },
    [clearTimer, debounceMs, minChars, reset, startRequest]
  );

  useLayoutEffect(() => {
    schedule(valueRef.current);
    return clearTimer;
  }, [schedule, clearTimer]);

  useLayoutEffect(
    () => () => {
      clearTimer();
      abortLatest();
    },
    [clearTimer, abortLatest]
  );

  const handleChange = (event) => {
    const nextValue = event.target.value;
    valueRef.current = nextValue;
    setValue(nextValue);

    // Every edit restarts the debounce, even if trimming gives the same query.
    schedule(nextValue);
  };

  const status =
    view.phase === "loading"
      ? "Searching..."
      : view.phase === "success" && view.results.length === 0
        ? "No results"
        : "";

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{status}</div>
      <ul aria-label="Results">
        {view.results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
      {view.phase === "error" && (
        <div role="alert">
          Something went wrong
          <button
            type="button"
            onClick={() => startRequest(valueRef.current.trim(), true)}
          >
            Retry
          </button>
        </div>
      )}
    </div>
  );
}
